70	// taken from mdn in the charAt doc page.
71	const getWholeChar = (str: string, i: number): string | false => {
72	  const code = str.charCodeAt(i);
73	  if (isNaN(code)) {
74	    return ''; // Position not found
75	  }
76	  if (code < 0xd800 || code > 0xdfff) {
77	    return str.charAt(i);
78	  }
79	
80	  // High surrogate (could change last hex to 0xDB7F to treat high private
81	  // surrogates as single characters)
82	  if (0xd800 <= code && code <= 0xdbff) {
83	    if (str.length <= i + 1) {
84	      throw 'High surrogate without following low surrogate';
85	    }
86	    const next = str.charCodeAt(i + 1);
87	    if (0xdc00 > next || next > 0xdfff) {
88	      throw 'High surrogate without following low surrogate';
89	    }
90	    return str.charAt(i) + str.charAt(i + 1);
91	  }
92	  // Low surrogate (0xDC00 <= code && code <= 0xDFFF)
93	  if (i === 0) {
94	    throw 'Low surrogate without preceding high surrogate';
95	  }
96	  const prev = str.charCodeAt(i - 1);
97	
98	  // (could change last hex to 0xDB7F to treat high private
99	  // surrogates as single characters)
100	  if (0xd800 > prev || prev > 0xdbff) {
101	    throw 'Low surrogate without preceding high surrogate';
102	  }
103	  // We can pass over low surrogates now as the second component
104	  // in a pair which we have already processed
105	  return false;
106	};
